Definition cem_slock_unlock_post (ra sp gp tp s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (L M lo shi : Z) (j3 j7 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a0 a1 a2 a3 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (L + 8, L + 9); (M + 8, M + 48)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' L [C8 (wz M); CB 1 [b8 0]; CB 7 j7]
    /\ rw_cells bsegs m' (M + 48) [C4 (wz 0); CB 1 [b8 1]; CB 3 j3]
    /\ APMutex m' (M + 8) 0
    /\ ACONST m' /\ stack0 m' lo shi.

Definition cem_slock_unlock_stmt : Prop :=
  forall (L M lo shi : Z) (j3 j7 : list byte) ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells bsegs m L [C8 (wz M); CB 1 [b8 1]; CB 7 j7] -> L mod 8 = 0 -> bv_unsigned sp <= L -> L + 16 <= shi ->
  rw_cells bsegs m (M + 48) [C4 (wz 0); CB 1 [b8 1]; CB 3 j3] -> APMutex m (M + 8) EBUSY -> 0 < M -> M mod 8 = 0 -> M + 56 <= aceil ->
  aapp M 56 -> accessible m (M + 48) 8 ->
  stk bsegs m lo (bv_unsigned sp) -> lo + ACEM_UNLOCK_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  ACONST m -> stack0 m lo shi ->
  evt bsegs (cem_slock_unlock_post ra sp gp tp s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc L M lo shi j3 j7 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz L) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_B_CEM_SLOCK_UNLOCK) fc None m (seg_rom bsegs)).

(* [comment removed for export] *)
Definition cem_slock_dtor_post (ra sp gp tp s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (lo shi : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a0 a1 a2 a3 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ ACONST m' /\ stack0 m' lo shi.

Definition cem_slock_dtor_stmt : Prop :=
  forall (L lo shi : Z) ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  ro_cells bsegs m (L + 8) [CB 1 [b8 0]] -> L mod 8 = 0 -> bv_unsigned sp <= L -> L + 16 <= shi ->
  stk bsegs m lo (bv_unsigned sp) -> lo + ACEM_SLDTOR_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  ACONST m -> stack0 m lo shi ->
  evt bsegs (cem_slock_dtor_post ra sp gp tp s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc lo shi m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz L) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_B_CEM_SLOCK_DTOR) fc None m (seg_rom bsegs)).

