Ltac sk_rd SK MU WM WS lo shi a w RD :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let SKc := fresh "SKc" in
    assert (SKc : stack0 mc lo shi) by (eapply stack0_transport; [exact SK| exact MU| exact WM| exact WS]);
    pose proof (stack0_read0_sr mc lo shi a w SKc ltac:(lia) ltac:(lia) ltac:(lia)) as RD; clear SKc
  end.
